@IsTest
private class StaticActionObservation {
    @IsTest static void observe() {
        Map<String,Object> staticResult=new Map<String,Object>{'kind'=>'static','stage'=>'directStatic'};
        try {
            OwnedStaticAction.run();
            staticResult.put('directCalls',OwnedStaticAction.calls);
            staticResult.put('stage','typeForName');
            Type token=Type.forName('OwnedStaticAction');
            staticResult.put('typeFound',token!=null);
            staticResult.put('stage','newInstance');
            Object value=token.newInstance();
            staticResult.put('instanceNonNull',value!=null);
            staticResult.put('stage','castInterface');
            OwnedAction action=(OwnedAction)value;
            staticResult.put('castNonNull',action!=null);
            staticResult.put('stage','invokeInterface');
            action.run();
            staticResult.put('afterCalls',OwnedStaticAction.calls);
            staticResult.put('stage','complete');
        } catch(Exception issue) {
            staticResult.put('exceptionType',issue.getTypeName());
            staticResult.put('exceptionMessage',issue.getMessage());
        }
        Map<String,Object> instanceResult=new Map<String,Object>{'kind'=>'instance','stage'=>'directInstance'};
        try {
            new OwnedInstanceAction().run();
            instanceResult.put('directCalls',OwnedInstanceAction.calls);
            instanceResult.put('stage','typeForName');
            Type token=Type.forName('OwnedInstanceAction');
            instanceResult.put('typeFound',token!=null);
            instanceResult.put('stage','newInstance');
            Object value=token.newInstance();
            instanceResult.put('instanceNonNull',value!=null);
            instanceResult.put('stage','castInterface');
            OwnedAction action=(OwnedAction)value;
            instanceResult.put('castNonNull',action!=null);
            instanceResult.put('stage','invokeInterface');
            action.run();
            instanceResult.put('afterCalls',OwnedInstanceAction.calls);
            instanceResult.put('stage','complete');
        } catch(Exception issue) {
            instanceResult.put('exceptionType',issue.getTypeName());
            instanceResult.put('exceptionMessage',issue.getMessage());
        }
        System.assertEquals('capture','STATIC_ACTION_OBSERVATION '+JSON.serialize(new Map<String,Object>{
            'staticResult'=>staticResult,'instanceResult'=>instanceResult
        }));
    }
}

