@IsTest
private class StaticActionObservation {
    private static void counts(Map<String,Object> row) {
        row.put('primaryCalls',OwnedStaticAction.calls);
        row.put('otherCalls',OwnedOtherStaticAction.calls);
        row.put('instanceCalls',OwnedInstanceAction.calls);
        row.put('unrelatedCalls',OwnedUnrelatedAction.calls);
    }
    private static void emit(Map<String,Object> row) {
        counts(row);
        System.assertEquals('capture','STATIC_ACTION_OBSERVATION '+JSON.serialize(row));
    }
    private static void reflect(String target) {
        Map<String,Object> row=new Map<String,Object>{'kind'=>'reflection','target'=>target,'stage'=>'typeForName'};
        try {
            Type token=Type.forName(target);
            row.put('typeFound',token!=null);
            row.put('stage','newInstance');
            Object value=token.newInstance();
            row.put('instanceNonNull',value!=null);
            row.put('stage','castInterface');
            OwnedAction action=(OwnedAction)value;
            row.put('castNonNull',action!=null);
            row.put('stage','invokeInterface');
            action.run();
            row.put('stage','complete');
        } catch(Exception issue) {
            row.put('exceptionType',issue.getTypeName());
            row.put('exceptionMessage',issue.getMessage());
        }
        emit(row);
    }
    @IsTest static void reflectedPrimary() { reflect('OwnedStaticAction'); }
    @IsTest static void reflectedOther() { reflect('OwnedOtherStaticAction'); }
    @IsTest static void reflectedInstance() { reflect('OwnedInstanceAction'); }
    @IsTest static void unrelatedCast() { reflect('OwnedUnrelatedAction'); }
    @IsTest static void directStaticControls() {
        Map<String,Object> row=new Map<String,Object>{'kind'=>'directStatic','stage'=>'primaryStatic'};
        try {
            OwnedStaticAction.run();
