        Map<String,Object> row=new Map<String,Object>{'kind'=>'nullInterface','stage'=>'castNull'};
        try {
            Object value=null;
            OwnedAction action=(OwnedAction)value;
            row.put('castIsNull',action==null);
            row.put('stage','invokeInterface');
            action.run();
            row.put('stage','complete');
        } catch(Exception issue) {
            row.put('exceptionType',issue.getTypeName());
            row.put('exceptionMessage',issue.getMessage());
        }
        emit(row);
    }
}

